schema_ddl:
CREATE TABLE clienti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codice_cliente TEXT NOT NULL UNIQUE,
    ragione_sociale TEXT NOT NULL,
    citta TEXT NOT NULL
);

CREATE TABLE vettori (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome_vettore TEXT NOT NULL,
    telefono TEXT
);

CREATE TABLE destinazioni (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    citta TEXT NOT NULL,
    provincia TEXT,
    nazione TEXT NOT NULL
);

CREATE TABLE mezzi_trasporto (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    targa TEXT NOT NULL UNIQUE,
    tipo_mezzo TEXT NOT NULL CHECK (tipo_mezzo IN ('camion', 'furgone', 'tir'))
);

CREATE TABLE spedizioni (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cliente_id INT NOT NULL REFERENCES clienti(id),
    vettore_id INT NOT NULL REFERENCES vettori(id),
    destinazione_id INT NOT NULL REFERENCES destinazioni(id),
    mezzo_id INT NOT NULL REFERENCES mezzi_trasporto(id),
    data_spedizione DATE NOT NULL,
    peso_kg NUMERIC(10,2) NOT NULL CHECK (peso_kg > 0),
    quantita_colli INT NOT NULL CHECK (quantita_colli > 0),
    costo_spedizione NUMERIC(12,2) NOT NULL CHECK (costo_spedizione >= 0)
);
